def windows(d, arm):
    """Per-phase (t0, t1) window for combined throughput.

    Prefer the '[phase] window t0=... t_fg_end=...' lines from notes.txt (exact).
    Fall back to the row t_end timestamps: t1 = last fg row's t_end (the fg
    loop ends immediately after), t0 = first fg row's t_end minus its
    predicted_ms (the request start, which is the loop start).
    """
    import re
    w = {}
    try:
        for l in open(f"{d}/{arm}/requests.jsonl"): 
            pass
        by_ph = {}
        for l in open(f"{d}/{arm}/requests.jsonl"):
            r = json.loads(l)
            by_ph.setdefault(r["phase"], []).append(r)
        for ph, rs in by_ph.items():
            fg = [r for r in rs if r["fg_bg"] == "fg" and "t_end" in r]
            if not fg:
                continue
            t1 = max(r["t_end"] for r in fg)
            t0 = min(r["t_end"] for r in fg) - (min((r.get("predicted_ms") or 0) for r in fg) / 1000.0)
            w[ph] = (t0, t1)
    except OSError:
        pass
    try:
        for l in open(f"{d}/{arm}/notes.txt"):
            m = re.search(r"\[(\S+)\] window t0=([\d.]+) t_fg_end=([\d.]+)", l)
            if m:
                w[m.group(1)] = (float(m.group(2)), float(m.group(3)))
    except OSError:
        pass
    return w

def combined(d, arm, data):
    """Tokens of fg plus bg rows that ended inside the fg window, over fg wall time."""
    w = windows(d, arm)
    print("
Combined two-slot throughput (fg + bg rows ending before fg ended) / fg window:
")
    print("| phase | arm | window s | fg tok | bg tok (in window) | combined tok/s |")
    print("|---|---|---|---|---|---|")
    for ph in PHASES:
        if ph not in w:
            continue
        t0, t1 = w[ph]
        dur = max(t1 - t0, 1e-9)
        fg = sum((r.get("predicted_n") or 0) for r in data[arm] if r["phase"] == ph and r["fg_bg"] == "fg")
        bg = sum((r.get("predicted_n") or 0) for r in data[arm] if r["phase"] == ph and r["fg_bg"] == "bg"
                 and r.get("t_end", 1e18) <= t1)
        print(f"| {ph} | {arm} | {dur:.0f} | {fg} | {bg} | {(fg + bg) / dur:.1f} |")

